DROP PROCEDURE IF EXISTS spacetime_ops_archive_test_scope_20261111;
DELIMITER $$
CREATE PROCEDURE spacetime_ops_archive_test_scope_20261111()
main: BEGIN
    DECLARE v_mode VARCHAR(16);
    DECLARE v_schema VARCHAR(64);
    DECLARE v_table VARCHAR(64);
    DECLARE v_ids JSON;
    DECLARE v_count BIGINT DEFAULT 0;
    DECLARE v_tables INT DEFAULT 0;
    DECLARE v_rows BIGINT DEFAULT 0;
    DECLARE v_done BOOLEAN DEFAULT FALSE;
    DECLARE v_created BOOLEAN DEFAULT FALSE;
    DECLARE v_lock INT DEFAULT 0;
    DECLARE v_cursor CURSOR FOR
        SELECT TABLE_NAME FROM information_schema.TABLES
        WHERE TABLE_SCHEMA='shikongxiehou_prod' AND TABLE_TYPE='BASE TABLE'
        ORDER BY TABLE_NAME;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done=TRUE;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        IF v_created THEN
            SET @archive_sql=CONCAT('UPDATE `',v_schema,'`.`_archive_manifest` SET state=''FAILED'' WHERE table_name=''__run__''');
            PREPARE archive_stmt FROM @archive_sql;
            EXECUTE archive_stmt;
            DEALLOCATE PREPARE archive_stmt;
            COMMIT;
        END IF;
        IF v_lock=1 THEN
            DO RELEASE_LOCK('spacetime_production_archive');
        END IF;
        RESIGNAL;
    END;

    SET v_mode=UPPER(@archive_mode);
    SET v_ids=CAST(@archive_user_ids AS JSON);
    IF @@server_uuid<>@archive_expected_server_uuid OR DATABASE()<>'shikongxiehou_prod' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='实例或数据库不匹配，停止归档';
    END IF;
    IF v_mode NOT IN ('PREVIEW','ARCHIVE') OR JSON_TYPE(v_ids)<>'ARRAY' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='仅支持 PREVIEW/ARCHIVE，账号名单必须为 JSON 数组';
    END IF;
    IF JSON_LENGTH(v_ids)=0 OR JSON_LENGTH(v_ids)<>@archive_expected_users THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='名单为空或数量与预期不符';
    END IF;
    SELECT COUNT(DISTINCT id) INTO v_count FROM JSON_TABLE(v_ids,'$[*]' COLUMNS(id BIGINT PATH '$' ERROR ON ERROR)) s WHERE id>0;
    IF v_count<>JSON_LENGTH(v_ids) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='名单包含重复或无效用户 ID';
    END IF;
    SELECT COUNT(*) INTO v_count FROM app_user u JOIN JSON_TABLE(v_ids,'$[*]' COLUMNS(id BIGINT PATH '$')) s ON s.id=u.id WHERE u.deleted=0;
    IF v_count<>@archive_expected_users THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='名单用户已变化或部分不存在，请重新确认，禁止按旧数量执行';
    END IF;

    SELECT '范围预览，尚未删除' AS 操作状态,v_count AS 候选账号数,
           (SELECT COUNT(*) FROM app_user WHERE deleted=0)-v_count AS 名单外保护账号数;
    SELECT u.id AS 候选用户ID,u.register_source AS 注册来源,u.account_status AS 账号状态
      FROM app_user u JOIN JSON_TABLE(v_ids,'$[*]' COLUMNS(id BIGINT PATH '$')) s ON s.id=u.id ORDER BY u.id;
    WITH s AS (SELECT id FROM JSON_TABLE(v_ids,'$[*]' COLUMNS(id BIGINT PATH '$')) j)
    SELECT '名单外账号持有的解锁记录' AS 交叉类型,COUNT(*) AS 数量
      FROM app_user_unlock_record WHERE target_user_id IN(SELECT id FROM s) AND user_id NOT IN(SELECT id FROM s)
    UNION ALL
    SELECT '单侧属于候选的聊天消息',COUNT(*) FROM app_message_record
      WHERE (sender_user_id IN(SELECT id FROM s))<>(receiver_user_id IN(SELECT id FROM s));
    SELECT TABLE_NAME AS 归档业务表,ENGINE AS 存储引擎
      FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE' ORDER BY TABLE_NAME;
    IF v_mode='PREVIEW' THEN LEAVE main; END IF;

    SET v_schema=@archive_schema;
    IF v_schema IS NULL OR v_schema NOT REGEXP '^spacetime_archive_[0-9]{8}_[a-zA-Z0-9_]{1,20}$'
       OR COALESCE(@archive_confirmation,'')<>'归档生产数据，不执行删除' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='归档库名或确认文字错误';
    END IF;
    IF COALESCE(@archive_writes_paused,0)<>1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='必须先完成维护停写，再明确设置 archive_writes_paused=1';
    END IF;
    IF EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND (EXTRA LIKE '%VIRTUAL GENERATED%' OR EXTRA LIKE '%STORED GENERATED%')) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='检测到生成列，请先适配显式归档列清单';
    END IF;
    IF @@autocommit<>1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='请在独立且 autocommit=1 的运维会话执行';
    END IF;
    IF EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE' AND ENGINE<>'InnoDB') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='存在非 InnoDB 表，无法保证一致性快照';
    END IF;
    SELECT GET_LOCK('spacetime_production_archive',0) INTO v_lock;
    IF COALESCE(v_lock,0)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='已有归档任务运行'; END IF;
    IF EXISTS(SELECT 1 FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=v_schema) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='归档库已存在，禁止覆盖，请使用新的批次库名';
    END IF;
    IF EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='_archive_manifest') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='源库存在与归档清单冲突的表名';
    END IF;

    SET @archive_sql=CONCAT('CREATE DATABASE `',v_schema,'` CHARACTER SET utf8mb4');
    PREPARE archive_stmt FROM @archive_sql; EXECUTE archive_stmt; DEALLOCATE PREPARE archive_stmt;
    SET @archive_sql=CONCAT('CREATE TABLE `',v_schema,'`.`_archive_manifest` (table_name VARCHAR(64) PRIMARY KEY,row_count BIGINT NOT NULL DEFAULT 0,state VARCHAR(20) NOT NULL,scope_ids JSON NULL,recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB');
    PREPARE archive_stmt FROM @archive_sql; EXECUTE archive_stmt; DEALLOCATE PREPARE archive_stmt;
    SET v_created=TRUE;
    SET @archive_sql=CONCAT('INSERT INTO `',v_schema,'`.`_archive_manifest`(table_name,state,scope_ids) VALUES(''__run__'',''BUILDING'',CAST(? AS JSON))');
    PREPARE archive_stmt FROM @archive_sql; EXECUTE archive_stmt USING @archive_user_ids; DEALLOCATE PREPARE archive_stmt;

    -- DDL 全部先完成，避免在数据快照事务内触发隐式提交。
    OPEN v_cursor;
    create_loop: LOOP
        FETCH v_cursor INTO v_table;
        IF v_done THEN LEAVE create_loop; END IF;
        SET @archive_sql=CONCAT('CREATE TABLE `',v_schema,'`.`',REPLACE(v_table,'`','``'),'` LIKE `shikongxiehou_prod`.`',REPLACE(v_table,'`','``'),'`');
        PREPARE archive_stmt FROM @archive_sql; EXECUTE archive_stmt; DEALLOCATE PREPARE archive_stmt;
        SET v_tables=v_tables+1;
    END LOOP;
    CLOSE v_cursor;

    SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    START TRANSACTION WITH CONSISTENT SNAPSHOT;
    SET v_done=FALSE;
    OPEN v_cursor;
    copy_loop: LOOP
        FETCH v_cursor INTO v_table;
        IF v_done THEN LEAVE copy_loop; END IF;
        SET @archive_sql=CONCAT('INSERT INTO `',v_schema,'`.`',REPLACE(v_table,'`','``'),'` SELECT * FROM `shikongxiehou_prod`.`',REPLACE(v_table,'`','``'),'`');
        PREPARE archive_stmt FROM @archive_sql; EXECUTE archive_stmt;
        SET v_rows=ROW_COUNT();
        DEALLOCATE PREPARE archive_stmt;
        SET @archive_sql=CONCAT('SELECT COUNT(*) INTO @archive_check_count FROM `',v_schema,'`.`',REPLACE(v_table,'`','``'),'`');
        PREPARE archive_stmt FROM @archive_sql; EXECUTE archive_stmt; DEALLOCATE PREPARE archive_stmt;
        IF @archive_check_count<>v_rows THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='归档行数核对失败，回滚本次数据复制';
        END IF;
        SET @archive_sql=CONCAT('INSERT INTO `',v_schema,'`.`_archive_manifest`(table_name,row_count,state) VALUES(?, ?, ''COPIED'')');
        SET @archive_table=v_table; SET @archive_rows=v_rows;
        PREPARE archive_stmt FROM @archive_sql; EXECUTE archive_stmt USING @archive_table,@archive_rows; DEALLOCATE PREPARE archive_stmt;
    END LOOP;
    CLOSE v_cursor;
    SET @archive_sql=CONCAT('UPDATE `',v_schema,'`.`_archive_manifest` SET state=''COMPLETE'',row_count=',v_tables,' WHERE table_name=''__run__''');
    PREPARE archive_stmt FROM @archive_sql; EXECUTE archive_stmt; DEALLOCATE PREPARE archive_stmt;
    COMMIT;
    DO RELEASE_LOCK('spacetime_production_archive');
    SET v_lock=0;
    SELECT '归档完成，未删除生产数据' AS 操作状态,v_schema AS 归档库,v_tables AS 表数;
END$$
DELIMITER ;
